def count_rotation(arr):
    n = len(arr)
    if n == 0:
        return 0

    # If array is already sorted (non-decreasing), 0 rotations
    if all(arr[i] <= arr[i + 1] for i in range(n - 1)):
        return 0

    # Otherwise, find index of minimum element (number of rotations)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] > arr[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo

assert count_rotation([3, 2, 1]) == 1
